select id, class_id, student_id, name, gender, created_at, updated_at, remark
from aiedu_student
where id = #{id,jdbcType=INTEGER}

select id, class_id, student_id, name, gender, created_at, updated_at, remark
from aiedu_student
where student_id = #{studentId,jdbcType=VARCHAR}
and class_id = #{classId,jdbcType=INTEGER}

select id, class_id, student_id, name, gender, created_at, updated_at, remark from aiedu_student
and class_id = #{classId,jdbcType=INTEGER}
and ( student_id like concat('%', #{search,jdbcType=VARCHAR}, '%') or name like concat('%', #{search,jdbcType=VARCHAR}, '%') )

select id, class_id, student_id, name, gender, created_at, updated_at, remark
from aiedu_student
where class_id = #{classId,jdbcType=INTEGER}
